module bemsa
  implicit none
  integer, parameter :: wp  = kind(1.0D0)
  real(wp)::r(6,6)
  real(wp), parameter :: a = 2.d0 

contains
  function emsav(x,c) result(v)
    implicit none
    real(wp),dimension(1:15)::x
    real(wp),dimension(0:848)::p
    real(wp),dimension(0:848)::c
    real(wp)::v
    
    call bemsav(x,p)
    v = dot_product(p,c)
    
    return
  end function emsav

  subroutine bemsav(x,p)
    implicit none
    real(wp),dimension(1:15)::x
    real(wp),dimension(0:14028)::m
    real(wp),dimension(0:848)::p
    ! ::::::::::::::::::::
    
    call evmono(x,m)
    call evpoly(m,p)
    
    return
  end subroutine bemsav
  
  
  subroutine get_x(xyz,x)
    implicit none
    integer :: i,j,k
    real(wp) :: xyz(6,3)
    real(wp),dimension(1:15)::x

    x( 1 ) = sqrt((xyz( 1 , 1 )-xyz( 2 , 1 ))**2+ &
          (xyz(1,2)-xyz(2,2))**2+ &
          (xyz(1,3)-xyz(2,3))**2)
    x( 2 ) = sqrt((xyz( 1 , 1 )-xyz( 3 , 1 ))**2+ &
          (xyz(1,2)-xyz(3,2))**2+ &
          (xyz(1,3)-xyz(3,3))**2)
    x( 3 ) = sqrt((xyz( 1 , 1 )-xyz( 4 , 1 ))**2+ &
          (xyz(1,2)-xyz(4,2))**2+ &
          (xyz(1,3)-xyz(4,3))**2)
    x( 4 ) = sqrt((xyz( 1 , 1 )-xyz( 5 , 1 ))**2+ &
          (xyz(1,2)-xyz(5,2))**2+ &
          (xyz(1,3)-xyz(5,3))**2)
    x( 5 ) = sqrt((xyz( 1 , 1 )-xyz( 6 , 1 ))**2+ &
          (xyz(1,2)-xyz(6,2))**2+ &
          (xyz(1,3)-xyz(6,3))**2)
    x( 6 ) = sqrt((xyz( 2 , 1 )-xyz( 3 , 1 ))**2+ &
          (xyz(2,2)-xyz(3,2))**2+ &
          (xyz(2,3)-xyz(3,3))**2)
    x( 7 ) = sqrt((xyz( 2 , 1 )-xyz( 4 , 1 ))**2+ &
          (xyz(2,2)-xyz(4,2))**2+ &
          (xyz(2,3)-xyz(4,3))**2)
    x( 8 ) = sqrt((xyz( 2 , 1 )-xyz( 5 , 1 ))**2+ &
          (xyz(2,2)-xyz(5,2))**2+ &
          (xyz(2,3)-xyz(5,3))**2)
    x( 9 ) = sqrt((xyz( 2 , 1 )-xyz( 6 , 1 ))**2+ &
          (xyz(2,2)-xyz(6,2))**2+ &
          (xyz(2,3)-xyz(6,3))**2)
    x( 10 ) = sqrt((xyz( 3 , 1 )-xyz( 4 , 1 ))**2+ &
          (xyz(3,2)-xyz(4,2))**2+ &
          (xyz(3,3)-xyz(4,3))**2)
    x( 11 ) = sqrt((xyz( 3 , 1 )-xyz( 5 , 1 ))**2+ &
          (xyz(3,2)-xyz(5,2))**2+ &
          (xyz(3,3)-xyz(5,3))**2)
    x( 12 ) = sqrt((xyz( 3 , 1 )-xyz( 6 , 1 ))**2+ &
          (xyz(3,2)-xyz(6,2))**2+ &
          (xyz(3,3)-xyz(6,3))**2)
    x( 13 ) = sqrt((xyz( 4 , 1 )-xyz( 5 , 1 ))**2+ &
          (xyz(4,2)-xyz(5,2))**2+ &
          (xyz(4,3)-xyz(5,3))**2)
    x( 14 ) = sqrt((xyz( 4 , 1 )-xyz( 6 , 1 ))**2+ &
          (xyz(4,2)-xyz(6,2))**2+ &
          (xyz(4,3)-xyz(6,3))**2)
    x( 15 ) = sqrt((xyz( 5 , 1 )-xyz( 6 , 1 ))**2+ &
          (xyz(5,2)-xyz(6,2))**2+ &
          (xyz(5,3)-xyz(6,3))**2)

    do i=1,6
       r(i,i)=0.d0
       do j=i+1,6
          r(i,j)=norm2(xyz(i,:)-xyz(j,:))
          r(j,i)=r(i,j)
       enddo
    enddo

    x(1) = dexp(-x(1)/a) 
    x(2) = dexp(-x(2)/a) 
    x(3) = dexp(-x(3)/a) 
    x(4) = dexp(-x(4)/a) 
    x(5) = dexp(-x(5)/a) 
    x(6) = dexp(-x(6)/a) 
    x(7) = dexp(-x(7)/a) 
    x(8) = dexp(-x(8)/a) 
    x(9) = dexp(-x(9)/a) 
    x(10) = dexp(-x(10)/a) 
    x(11) = dexp(-x(11)/a) 
    x(12) = dexp(-x(12)/a) 
    x(13) = dexp(-x(13)/a) 
    x(14) = dexp(-x(14)/a) 
    x(15) = dexp(-x(15)/a) 

  end subroutine

